"use client";
/* Inbox, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Inbox(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("inbox"); }, []);
  return React.createElement("piix-sprite", { "name": "inbox", ...piixAttrs(props) });
}

export default Inbox;
